import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity @jakarta.persistence.Table(name = "interest")
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xrf21 extends Xwb79Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Xrd81 user;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_color_id")
    private Xfp92 productColor;


    public void assignUser(Xrd81 user) {
        if (this.user != null) {
            this.user.getInterests().remove(this);
        }
        this.user = user;
        user.getInterests().add(this);
    }

    public void unassignUser() {
        if (this.user != null) {
            this.user.getInterests().remove(this);
            this.user = null;
        }
    }

    public void assignProductColor(Xfp92 productColor) {
        if (this.productColor != null) {
            this.productColor.getInterests().remove(this);
        }
        this.productColor = productColor;
        productColor.getInterests().add(this);
    }

    public void unassignProductColor() {
        if (this.productColor != null) {
            this.productColor.getInterests().remove(this);
            this.productColor = null;
        }
    }
}
package com.fream.back.domain.m15.service.command;

import com.fream.back.domain.m15.dto.Xkh73DTO;
import com.fream.back.domain.m15.dto.Xkh73RequestDTO;
import com.fream.back.domain.m15.entity.Xkh73;
import com.fream.back.domain.m15.entity.Xzv64;
import com.fream.back.domain.m15.entity.Xkh73Type;
import com.fream.back.domain.m15.exception.Xkh73ErrorCode;
import com.fream.back.domain.m15.exception.Xkh73Exception;
import com.fream.back.domain.m15.repository.Xkh73Repository;
import com.fream.back.domain.m16.entity.Xdg64;
import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.domain.m13.repository.Xrd81Repository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.messaging.simp.SimpMessagingTemplate;
